-- AmirNet full platform schema + seed: 50 full simulations, 2500 questions, 200 vocabulary words
-- Run this in Supabase SQL Editor after deploying this package.
begin;

create extension if not exists pgcrypto;

create table if not exists users (
  id text primary key default gen_random_uuid()::text,
  "openId" text unique,
  name text,
  email text unique,
  "loginMethod" text default 'email',
  "passwordHash" text,
  role text default 'user',
  premium boolean default false,
  "subscriptionStatus" text default 'free',
  "subscriptionProvider" text,
  "subscriptionId" text,
  "currentPeriodEnd" timestamp,
  "planType" text,
  "lemonCustomerId" text,
  "createdAt" timestamp default now(),
  "updatedAt" timestamp default now(),
  "lastSignedIn" timestamp default now()
);

create table if not exists sessions (
  id text primary key,
  "userId" text not null,
  "expiresAt" timestamp not null,
  "createdAt" timestamp default now()
);

create table if not exists subscription_plans (
  id serial primary key,
  name varchar(64) not null,
  "nameHe" varchar(128) not null,
  "priceIls" numeric(10,2) not null,
  "durationDays" integer not null,
  "stripePriceId" varchar(128),
  "lemonSqueezyVariantId" varchar(128),
  "maxExamsPerMonth" integer default 999,
  "maxQuestionsPerDay" integer default 999,
  "hasAdaptiveLearning" boolean default true,
  "hasVocabularyModule" boolean default true,
  "hasDetailedAnalytics" boolean default true,
  "hasAiHints" boolean default true,
  "isMilitary" boolean default false,
  "isActive" boolean default true,
  "createdAt" timestamp default now() not null
);

create table if not exists subscriptions (
  id serial primary key,
  "userId" text not null,
  "planId" integer not null,
  "stripeSubscriptionId" varchar(256),
  "stripeCustomerId" varchar(256),
  provider varchar(64) default 'manual',
  "providerSubscriptionId" varchar(256),
  "providerCustomerId" varchar(256),
  "providerOrderId" varchar(256),
  status text default 'trial' not null,
  "startedAt" timestamp default now() not null,
  "expiresAt" timestamp default now() + interval '30 days' not null,
  "cancelledAt" timestamp,
  "createdAt" timestamp default now() not null,
  "updatedAt" timestamp default now() not null
);

create table if not exists payments (
  id serial primary key,
  "userId" text not null,
  "subscriptionId" integer,
  "stripePaymentIntentId" varchar(256),
  provider varchar(64) default 'manual',
  "providerPaymentId" varchar(256),
  "providerOrderId" varchar(256),
  "amountIls" numeric(10,2) not null default 0,
  status text default 'pending' not null,
  "createdAt" timestamp default now() not null
);

alter table users alter column id drop default;
alter table users alter column id type text using id::text;
alter table users alter column id set default gen_random_uuid()::text;
alter table users alter column email drop not null;
alter table users add column if not exists premium boolean default false;
alter table users add column if not exists "subscriptionStatus" text default 'free';
alter table users add column if not exists "subscriptionProvider" text;
alter table users add column if not exists "subscriptionId" text;
alter table users add column if not exists "currentPeriodEnd" timestamp;
alter table users add column if not exists "planType" text;
alter table users add column if not exists "lemonCustomerId" text;

alter table subscription_plans add column if not exists "nameHe" varchar(128);
alter table subscription_plans add column if not exists "priceIls" numeric(10,2);
alter table subscription_plans add column if not exists "durationDays" integer;
alter table subscription_plans add column if not exists "lemonSqueezyVariantId" varchar(128);
alter table subscription_plans add column if not exists "isActive" boolean default true;

values (3, 'premium', 'פרימיום', 99, 30, '1710097', 999, 999, true, true, true, true, true)
on conflict (id) do update set
  name = excluded.name,
  "nameHe" = excluded."nameHe",
  "priceIls" = excluded."priceIls",
  "durationDays" = excluded."durationDays",
  "lemonSqueezyVariantId" = excluded."lemonSqueezyVariantId",
  "maxExamsPerMonth" = excluded."maxExamsPerMonth",
  "maxQuestionsPerDay" = excluded."maxQuestionsPerDay",
  "hasAdaptiveLearning" = true,
  "hasVocabularyModule" = true,
  "hasDetailedAnalytics" = true,
  "hasAiHints" = true,
  "isActive" = true;


create table if not exists exams (
  id serial primary key,
  name varchar(256) not null,
  "nameHe" varchar(256),
  "totalQuestions" integer default 50,
  "timeLimitMinutes" integer default 39,
  "isAdaptive" boolean default false,
  "isSimulation" boolean default true,
  "createdAt" timestamp default now() not null
);

create table if not exists passages (
  id serial primary key,
  title text,
  body text not null,
  "wordCount" integer,
  difficulty integer default 5,
  topic varchar(128),
  status text default 'approved' not null,
  "createdAt" timestamp default now() not null,
  "updatedAt" timestamp default now() not null
);

create table if not exists questions (
  id serial primary key,
  type text not null,
  difficulty integer default 5 not null,
  "questionText" text not null,
  "choiceA" text not null,
  "choiceB" text not null,
  "choiceC" text not null,
  "choiceD" text not null,
  "correctAnswer" text not null,
  "explanationHe" text,
  "whyWrongAHe" text,
  "whyWrongBHe" text,
  "whyWrongCHe" text,
  "whyWrongDHe" text,
  tags jsonb default '[]'::jsonb,
  "estimatedTimeSec" integer default 45,
  "cefrLevel" varchar(8),
  "passageId" integer,
  status text default 'approved' not null,
  "isPilot" boolean default false,
  "reportCount" integer default 0,
  "createdAt" timestamp default now() not null,
  "updatedAt" timestamp default now() not null
);

create table if not exists exam_attempts (
  id serial primary key,
  "userId" text not null,
  "examId" integer,
  mode text default 'practice' not null,
  status text default 'in_progress' not null,
  score integer,
  "estimatedAmirnetScore" integer,
  "totalQuestions" integer default 0,
  "correctAnswers" integer default 0,
  "timeTakenSeconds" integer,
  "startedAt" timestamp default now() not null,
  "completedAt" timestamp,
  "questionIds" jsonb default '[]'::jsonb
);

create table if not exists answers (
  id serial primary key,
  "attemptId" integer not null,
  "userId" text not null,
  "questionId" integer not null,
  "selectedAnswer" text,
  "isCorrect" boolean,
  "timeTakenSeconds" integer,
  "usedHint" boolean default false,
  "answeredAt" timestamp default now() not null
);

create table if not exists user_weakness_profiles (
  id serial primary key,
  "userId" text not null unique,
  "vocabularyAccuracy" numeric(5,2) default 0,
  "sentenceCompletionAccuracy" numeric(5,2) default 0,
  "restatementAccuracy" numeric(5,2) default 0,
  "readingComprehensionAccuracy" numeric(5,2) default 0,
  "avgTimeSec" numeric(6,2) default 0,
  "weakTags" jsonb default '[]'::jsonb,
  "estimatedScore" integer default 100,
  "streakDays" integer default 0,
  "lastPracticeAt" timestamp,
  "totalQuestionsAnswered" integer default 0,
  "updatedAt" timestamp default now() not null
);

create table if not exists vocabulary_words (
  id serial primary key,
  word varchar(128) not null,
  definition text not null,
  "definitionHe" text not null,
  "exampleSentence" text,
  difficulty integer default 5,
  "cefrLevel" varchar(8),
  tags jsonb default '[]'::jsonb,
  "audioUrl" varchar(512),
  frequency integer default 1,
  "createdAt" timestamp default now() not null
);

create table if not exists user_vocabulary_progress (
  id serial primary key,
  "userId" text not null,
  "wordId" integer not null,
  "masteryLevel" integer default 0,
  "nextReviewAt" timestamp,
  "reviewCount" integer default 0,
  "lastReviewedAt" timestamp
);

create table if not exists saved_questions (
  id serial primary key,
  "userId" text not null,
  "questionId" integer not null,
  "savedAt" timestamp default now() not null
);

create table if not exists question_reports (
  id serial primary key,
  "userId" text not null,
  "questionId" integer not null,
  reason varchar(512),
  status text default 'pending' not null,
  "createdAt" timestamp default now() not null
);


alter table user_weakness_profiles alter column "userId" type text using "userId"::text;

delete from answers;
delete from exam_attempts;
delete from questions;
delete from passages;
delete from exams;
delete from vocabulary_words;
alter sequence if exists questions_id_seq restart with 1;
alter sequence if exists passages_id_seq restart with 1;
alter sequence if exists exams_id_seq restart with 1;
alter sequence if exists vocabulary_words_id_seq restart with 1;
